import React, { useEffect, useState } from 'react';
import { Badge, Button, Form, Spinner } from 'react-bootstrap';
import { reportFilterFormContainer, staffSalaryBtn } from './formFieldData';
import Table from '../../../components/Table';
import { dateConversion, findArrObj, showConfirmationDialog, showMessage } from '../../../utils/AllFunction';
import { usePageTitle, useRedux } from '../../../hooks'
import { NotificationContainer } from 'react-notifications';
import { getBranchRequest, getClaimRequest, getDepartmentRequest, getPetrolAllowanceReportRequest, getPetrolAllowanceRequest, getStaffRequest, resetGetBranch, resetGetClaim, resetGetDepartment, resetGetPetrolAllowance, resetGetPetrolAllowanceReport, resetGetStaff } from '../../../redux/actions';
import moment from 'moment';
import * as XLSX from "xlsx";
import { useNavigate } from 'react-router-dom';
import _ from 'lodash';
import { baseURL } from '../../../api/ApiConfig';
import noProfile from '../../../assets/images/noprofile_images.jpg';

function Index() {

    usePageTitle({
        title: 'Report',
        breadCrumbItems: [
            {
                path: '/report/petrol-allowance-report',
                label: 'Report',
            },
            {
                path: '/petrol-allowance-report',
                label: 'Petrol Allowance Report',
                active: true,
            },
        ],
    });

    const { dispatch, appSelector } = useRedux();
    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData[0].pagePermission, 'label', "Petrol Allowance Report");
    const accessIds = (pageAccessData[0]?.access || '').split(',').map(id => id.trim());// for access create and update and delete actions ['1', '2', '3', '4', '5', '6']
    const branchIdforRole = localData[0]?.branchId || 0; // for branch list can only show
    const roleIdforRole = localData[0].roleId; // for role Permission (1.superadmin,2.admin)

    const navigate = useNavigate();

    const { getStaffSuccess,
        getStaffList,
        getStaffFailure,
        getPetrolAllowanceSuccess, getPetrolAllowanceList, getPetrolAllowanceFailure,
        getBranchSuccess, getBranchList, getBranchFailure,
        getDepartmentSuccess, getDepartmentList, getDepartmentFailure,

        getPetrolAllowanceReportSuccess,
        getPetrolAllowanceReportData,
        getPetrolAllowanceReportFailure,

        errorMessage,
    } = appSelector((state) => ({


        getStaffSuccess: state.staffReducer.getStaffSuccess,
        getStaffList: state.staffReducer.getStaffList,
        getStaffFailure: state.staffReducer.getStaffFailure,

        getBranchSuccess: state.branchReducer.getBranchSuccess,
        getBranchList: state.branchReducer.getBranchList,
        getBranchFailure: state.branchReducer.getBranchFailure,

        getDepartmentSuccess: state.departmentReducer.getDepartmentSuccess,
        getDepartmentList: state.departmentReducer.getDepartmentList,
        getDepartmentFailure: state.departmentReducer.getDepartmentFailure,

        getPetrolAllowanceSuccess: state.petrolAllowanceReducer.getPetrolAllowanceSuccess,
        getPetrolAllowanceList: state.petrolAllowanceReducer.getPetrolAllowanceList,
        getPetrolAllowanceFailure: state.petrolAllowanceReducer.getPetrolAllowanceFailure,

        getPetrolAllowanceReportSuccess: state.petrolAllowanceReducer.getPetrolAllowanceReportSuccess,
        getPetrolAllowanceReportData: state.petrolAllowanceReducer.getPetrolAllowanceReportData,
        getPetrolAllowanceReportFailure: state.petrolAllowanceReducer.getPetrolAllowanceReportFailure,

        errorMessage: state.petrolAllowanceReducer.errorMessage,
    }));

    const parentColumns = [
        {
            Header: 'S.No',
            accessor: 'id',
        },
        {
            Header: 'Staff',
            accessor: 'staffName',
            Cell: ({ row }) => (
                <div style={{ display: 'flex', alignItems: 'center' }}>
                    <img
                        src={row?.original?.staffProfile ? `${baseURL}${row?.original.staffProfile}` : noProfile}
                        alt="staffProfile"
                        className="rounded-circle"
                        crossOrigin="anonymous"
                        onError={(e) => {
                            e.target.onerror = null;
                            e.target.src = noProfile;
                        }}
                        style={{ width: "40px", height: "40px", objectFit: "cover", marginRight: "10px" }}
                    />
                    <div>
                        <div style={{ fontWeight: 600 }}>{row.original.staffName}</div>
                        <div style={{ fontSize: 12, color: '#888' }}>{row.original.staffCode}</div>
                    </div>
                </div>
            )
        },
        {
            Header: 'Total Km',
            accessor: 'totalKmSum',
        },
        {
            Header: 'Total Asked Amount',
            accessor: 'totalAmountSum',
        }
    ];

    const childColumns = [
        {
            Header: 'Date',
            accessor: 'allowanceDate',
            Cell: ({ value }) => dateConversion(value, 'DD/MM/YYYY')
        },
        {
            Header: 'From',
            accessor: 'fromPlace',
            Cell: ({ value }) => {
                return (
                    <div>
                        {Array.isArray(value)
                            ? value.map((item, index) => <div key={index}>{item}</div>)
                            : value?.split(/[\n,]+/).map((word, index) => <div key={index}>{word}</div>)
                        }
                    </div>
                );
            }
        },
        {
            Header: 'To',
            accessor: 'toPlace',
            Cell: ({ value }) => {
                return (
                    <div>
                        {Array.isArray(value)
                            ? value.map((item, index) => <div key={index}>{item}</div>)
                            : value?.split(/[\n,]+/).map((word, index) => <div key={index}>{word}</div>)
                        }
                    </div>
                );
            }
        },
        {
            Header: 'Activity',
            accessor: 'activityName',
        },
        {
            Header: 'Km',
            accessor: 'totalKm',
        },
        {
            Header: 'Asked Amount',
            accessor: 'totalAmount',
        },
        {
            Header: 'Image Status',
            accessor: 'isImageApproved',
            Cell: ({ row }) => {
                const statusMap = {
                    0: { text: 'Cancelled', color: 'danger' },
                    1: { text: 'Approved', color: 'success' },
                    2: {
                        text: row?.billImageName ? 'Pending' : 'Img not upload',
                        color: row?.billImageName ? 'warning' : 'primary'
                    }
                };
                const status = statusMap[row?.isImageApproved] || statusMap[2];
                return <Badge bg={status.color}>{status.text}</Badge>;
            }
        },
        {
            Header: 'Actions',
            accessor: 'actions',
            Cell: ({ row }) => {
                const hasImage = !!row?.billImageName;
                return (
                    <div>
                        <span className="text-success me-2 cursor-pointer" onClick={(e) => {
                            e.stopPropagation();
                            onPrintDesign(row)
                        }}>
                            <i className={'fe-printer'}></i>
                        </span>
                    </div>
                );
            }
        }
    ];

    const [state, setState] = useState({
        fromDate: moment().startOf('isoWeek').format('YYYY-MM-DD'),
        toDate: moment().format('YYYY-MM-DD'),
        durationId: 0,
        branchId: branchIdforRole,
        departmentId: 0,
        staffId: 0,
    });
    const [optionListState, setOptionListState] = useState({
        departmentList: [
            {
                "departmentId": 0,
                "departmentName": "All",
            },
        ],
        branchList: [{
            "branchId": 0,
            "branchName": "All",
        }],
        durationList: [
            {
                "durationId": 0,
                "durationName": "Month",
            },
            {
                "durationId": 1,
                "durationName": "Year",
            },
        ],
        staffList: [
            {
                "staffId": 0,
                "staffName": "All",
            }
        ]
    })
    const [formContain, setFormContain] = useState(reportFilterFormContainer);
    const [parentList, setParentList] = useState([]);
    const [isLoading, setIsLoading] = useState(false);

    useEffect(() => {
        setIsLoading(true)
        dispatch(getBranchRequest());
        dispatch(getDepartmentRequest());

        const req = {
            branchId: branchIdforRole
        }
        dispatch(getStaffRequest(roleIdforRole != 1 && req));
        const searchReq = {
            fromDate: state?.fromDate,
            toDate: state?.toDate,
            durationId: state.durationId,
            branchId: branchIdforRole || '',
            staffId: state.staffId || '',
            departmentId: state.departmentId || '',
        }
        dispatch(getPetrolAllowanceRequest(searchReq));
    }, []);

    useEffect(() => {
        if (roleIdforRole != 1) {
            let arr = reportFilterFormContainer;
            const updatedFormFields = _.filter(
                reportFilterFormContainer[0].formFields,
                (field) => field.name !== 'branchId'
            );
            arr[0].formFields = updatedFormFields;
            setFormContain(arr);
        }
    }, [reportFilterFormContainer, roleIdforRole]);

    useEffect(() => {
        if (getStaffSuccess) {
            setIsLoading(false);
            setOptionListState({
                ...optionListState,
                staffList: roleIdforRole != 1 ? getStaffList : [...optionListState.staffList, ...getStaffList],
            });
            dispatch(resetGetStaff());
        } else if (getStaffFailure) {
            setIsLoading(false);
            setOptionListState({
                ...optionListState,
                staffList: [],
            });
            dispatch(resetGetStaff());
        }
    }, [getStaffSuccess, getStaffFailure]);

    useEffect(() => {
        if (getBranchSuccess) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                branchList: [...optionListState.branchList, ...getBranchList],
            })
            dispatch(resetGetBranch())
        } else if (getBranchFailure) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                branchList: []
            })
            dispatch(resetGetBranch())
        }
    }, [getBranchSuccess, getBranchFailure]);

    useEffect(() => {
        if (getDepartmentSuccess) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                departmentList: [...optionListState.departmentList, ...getDepartmentList],
            })
            dispatch(resetGetDepartment())
        } else if (getDepartmentFailure) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                departmentList: []
            })
            dispatch(resetGetDepartment())
        }
    }, [getDepartmentSuccess, getDepartmentFailure]);


    useEffect(() => {
        if (getPetrolAllowanceSuccess) {
            setIsLoading(false)
            const groupedData = _.values(
                _.groupBy(getPetrolAllowanceList, 'staffId')
            ).map((group, index) => {
                const staff = group[0];
                return {
                    id: index + 1,
                    staffId: staff.staffId,
                    staffName: staff.staffName,
                    staffCode: staff.staffCode,
                    staffProfile: staff.staffProfile,
                    totalKmSum: _.sumBy(group, (o) => Number(o.totalKm) || 0),
                    totalAmountSum: _.sumBy(group, (o) => Number(o.totalAmount) || 0),

                    children: group, // sub-rows
                };
            });
            setParentList(groupedData);
            dispatch(resetGetPetrolAllowance())
        } else if (getPetrolAllowanceFailure) {
            setIsLoading(false)
            setParentList([])
            dispatch(resetGetPetrolAllowance())
        }
    }, [getPetrolAllowanceSuccess, getPetrolAllowanceFailure]);


    useEffect(() => {
        if (getPetrolAllowanceReportSuccess) {
            setIsLoading(false);
            if (getPetrolAllowanceReportData.length > 0) {
                navigate('/petrol-allowance-report', { state: getPetrolAllowanceReportData[0], month: state.toDate })
            }
            dispatch(resetGetPetrolAllowanceReport());
        } else if (getPetrolAllowanceReportFailure) {
            setIsLoading(false);
            dispatch(resetGetPetrolAllowanceReport());
        }
    }, [getPetrolAllowanceReportSuccess, getPetrolAllowanceReportFailure]);

    const onPrintDesign = (data) => {
        const reqReport = {
            staffId: data?.staffId,
            fromDate: state?.fromDate,
            toDate: state?.toDate
        }
        dispatch(getPetrolAllowanceReportRequest(reqReport));
    }

    const onFromDate = (event, formName) => {
        setState({
            ...state,
            [formName]: event.target.value
        })
        const filterDate = {
            fromDate: event.target.value,
            toDate: state.toDate,
            durationId: state.durationId,
            branchId: state.branchId || '',
            staffId: state.staffId || '',
            departmentId: state.departmentId || '',
        }
        dispatch(getPetrolAllowanceRequest(filterDate));
    }
    const onToDate = (event, formName) => {
        setState({
            ...state,
            [formName]: event.target.value
        })
        const filterDate = {
            toDate: event.target.value,
            fromDate: state.fromDate,
            durationId: state.durationId,
            branchId: state.branchId || '',
            staffId: state.staffId || '',
            departmentId: state.departmentId || '',
        }
        dispatch(getPetrolAllowanceRequest(filterDate));
    }

    const onDepartmentFilter = (option, formName, uniqueKey, displayKey) => {
        const filterDepartment = {
            departmentId: option[uniqueKey] || '',
            branchId: state?.branchId || '',
            fromDate: state?.fromDate,
            toDate: state?.toDate,
            durationId: state.durationId,
            staffId: state.staffId || '',
        }
        dispatch(getPetrolAllowanceRequest(filterDepartment));
        setIsLoading(true);
        setState({
            ...state,
            [formName]: option[uniqueKey],
        })
    }

    const onBranchFilter = (option, formName, uniqueKey, displayKey) => {
        const filterBranch = {
            branchId: option[uniqueKey] || '',
            departmentId: state?.departmentId || '',
            fromDate: state?.fromDate,
            toDate: state?.toDate,
            durationId: state.durationId,
            staffId: state.staffId || '',
        }
        dispatch(getPetrolAllowanceRequest(filterBranch));
        setIsLoading(true);
        setState({
            ...state,
            [formName]: option[uniqueKey],
        })
    }
    const onStaffFilter = (option, formName, uniqueKey, displayKey) => {
        const filterBranch = {
            staffId: option[uniqueKey] || '',
            fromDate: state?.fromDate,
            toDate: state?.toDate,
            durationId: state.durationId,
            departmentId: state.departmentId || '',
            branchId: state?.branchId || '',
        }
        dispatch(getPetrolAllowanceRequest(filterBranch));
        setIsLoading(true);
        setState({
            ...state,
            [formName]: option[uniqueKey],
        })
    }

    const onDownload = () => {
        const yearMonth = moment(state?.allowanceDate).format("MMMM YYYY");
        const additionalDetails = `Petrol Allowance Report for ${yearMonth}`;
        const reportGeneratedDate = `Report Generated On: ${moment().format("DD-MM-YYYY")}`;

        const header = [
            [additionalDetails],
            [reportGeneratedDate],
            [],
            [
                "S.no",
                "Staff Code",
                "Staff Name",
                "Branch Name",
                "Department Name",
                "Designation Name",
                "Allowance Date",
                "From Place",
                "To Place",
                "Total Km",
                "Activities"
            ]
        ];

        let serialNo = 1;
        const rows = parentList.flatMap((parent) =>
            parent.children?.map((child) => [
                serialNo++,
                parent.staffCode,
                parent.staffName,
                parent.branchName,
                parent.departmentName,
                parent.designationName,
                moment(child.allowanceDate).format("DD-MM-YYYY"),
                child.fromPlace,
                child.toPlace,
                child.totalKm,
                child.activityName
            ])
        );

        const worksheet = XLSX.utils.aoa_to_sheet([...header, ...rows]);

        worksheet["!cols"] = [
            { wch: 6 },  // S.no
            { wch: 15 }, // Staff Code
            { wch: 20 }, // Staff Name
            { wch: 20 }, // Branch
            { wch: 20 }, // Department
            { wch: 20 }, // Designation
            { wch: 15 }, // Allowance Date
            { wch: 15 }, // From
            { wch: 15 }, // To
            { wch: 10 }, // Km
            { wch: 20 }, // Activity
        ];

        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, "Petrol Allowance Report");

        XLSX.writeFile(workbook, `K3-Petrol-Allowance-Report-${yearMonth}.xlsx`);
    };



    return (
        <React.Fragment>
            <NotificationContainer />
            {isLoading ? <div className='bg-light opacity-0.25'>
                <div className="d-flex justify-content-center m-5">
                    <Spinner className='mt-5 mb-5' animation="border" />
                </div>
            </div> :
                <Table
                    columns={parentColumns}
                    childColumns={childColumns}
                    Title={'Petrol Allowance Report List'}
                    isExpandable={true}
                    data={parentList || []}
                    pageSize={5}
                    toggle={false}
                    pagination={false}
                    filterTbl={true}
                    footerTbl={true}
                    filterFormContainer={formContain}
                    onChangeCallBack={{ "onToDate": onToDate, "onFromDate": onFromDate, "onDepartmentFilter": onDepartmentFilter, "onBranchFilter": onBranchFilter, "onStaffFilter": onStaffFilter }}
                    onClickCallBack={{ "onDownload": onDownload }}
                    optionListState={optionListState}
                    setState={setState}
                    state={state}
                    noOfColumns={1}
                />}
        </React.Fragment>
    );
}

export default Index;
